// Capability sentences end with {{F-ID}} (features.json). Numbers and prices are never typed here: placeholders such as __FREE_DOCS__ are filled by the registry from plans.js.
import { PRODUCT_PAGES } from "./product.js";
const from = (p) => PRODUCT_PAGES.find((x) => x.path === p);
const KEEP = (...x) => x;
const derive = (src, over) => { const b = from(src); return { ...b, addFrom: src, ...over, blocks: [...(over.pre ?? []), ...(over.blocks ?? b.blocks)] }; };

