const insert = (p, extra) => { const i = p.blocks.findLastIndex((b) => b.t === "faq"); return { ...p, blocks: i < 0 ? [...p.blocks, ...extra] : [...p.blocks.slice(0, i), ...extra, ...p.blocks.slice(i)] }; };
const FAQ_MORE = {
  "/features": [["Do I need to write code to use any of this?", "No. Every feature on this page works in the app, and the demo lets you click through it with no sign-up. The API, SDKs and command line are there for the day you want to put signing inside your own product. {{F-API}}"], ["What does it cost?", "Free is __FREE_DOCS__ documents a month with test mode, the API and webhooks. Pro is one flat price for the whole workspace, and the page for pricing has the full table. {{F-PRO}}"]],
  "/features/how-it-works": [["Can I stop a document after it is sent?", "Yes. You can void it, and anyone who was asked to sign is told it was cancelled. A document can also expire on the date you set, and the sender is told when it lapses unsigned. {{F-SEND}}"], ["Can signers decline?", "Yes. A person can decline and say why, and you are told at once. The decline is part of the record. {{F-SIGN}}"]],
  "/features/embedded-signing": [["Does it work on a self-hosted install?", "Yes. Use your own address for the embed script, which is your install's web address followed by /embed/index.js. {{F-SELFHOST}}"], ["How long does a session last?", "An hour. Ask again each time the page loads. The five newest links for a seat keep working until their hour is up, so a page that reloads does not break a form that is already open. {{F-EMBED}}"]],
  "/features/test-mode": [["Does a test signature count as a real one?", "No. Signing a test document records nothing as a real signature event, and the document is marked as a practice run on its pages and in the API. {{F-TESTMODE}}"], ["Can I test payments?", "Not against real cards. Test mode does not take payments. {{F-PAYMENTS}}"], ["Where do I see a document's test flag?", "In the API the document carries test: true, and the app marks it with a Test chip and a banner on the signing page. {{F-TESTMODE}}"]],
  "/features/agent-ready": [["Can an assistant see signing links?", "No. No tool returns a signing link, a code or the key. {{F-MCP}}"], ["Where do I get a key for an assistant?", "In the app, under Developers, API keys. Give it only the scopes it needs, and start with a test key. {{F-SCOPES}}"], ["What about assistants that cannot run a program?", "A hosted connector does the same job for them. {{F-MCP}}"], ["Is an assistant's work on the record?", "Yes. What an assistant does through a key is recorded like what a person does: which key, which document and when, in the same audit log your team reads. Revoke the key and its access ends at once. {{F-AUDIT}}"]],
  "/features/white-label": [["Does branding cost extra?", "No. Your logo, colour, welcome note, sender name and reply-to address are on every plan. {{F-BRANDING}}"], ["Can one document have its own subject and message?", "Yes. On the Details step of a send you can change the subject and the message for that document alone, and from the API you can set the reply-to address and the sender name. {{F-EMAILCTRL}}"]],
};
const moreFaq = (p) => { const x = FAQ_MORE[p.path]; if (!x) return p; const i = p.blocks.findLastIndex((b) => b.t === "faq"); if (i < 0) return p; const blocks = p.blocks.slice(); blocks[i] = { ...blocks[i], items: [...blocks[i].items, ...x] }; return { ...p, blocks }; };
export const FEATURE_PAGES = RAW.map((p) => (MORE[p.path] ? insert(p, MORE[p.path]) : p)).map(moreFaq);
